def _svg(key, size=26):
    inner = _ICON.get(key) or _ICON["sparkles"]
    return (f'<svg viewBox="0 0 24 24" width="{size}" height="{size}" fill="none" stroke="currentColor" '
            f'stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>')


def icon_for(text, i=0):
    """Pick an icon by what the service is about; fall back to a rotating generic so three cards never clash."""
    t = str(text or "").lower()
    for words, key in _WORD_ICON:
        if any(w in t for w in words):
            return key
    return _DEFAULT_CYCLE[i % len(_DEFAULT_CYCLE)]


def svg_for(text, i=0, size=26):
    return _svg(icon_for(text, i), size)
